// <diletta-icon-button> — a INSTÂNCIA WEB de `design-system-icon-button`.
//
// 112 usos no BackOffice. Ela ficou fora da tradução até 07/09/2026 porque as duas
// paletas internas dela liam DEGRAU — e um degrau que coincide com papel nenhum
// segura a peça inteira.
import { papeisDe, estiloDa, eixo } from './base.js';

const SLUG = 'design-system-icon-button';
const TYPE = ['primary', 'secondary', 'secondaryPrimary', 'tertiary', 'tertiaryPrimary'];
// Medido no _sizeSpec do Dart, não estimado.
const PORTE = {
  sm: { box: 32, icone: 14 },
  md: { box: 40, icone: 18 },
  lg: { box: 56, icone: 22 },
};
const ALVO = 44;

class DilettaIconButton extends HTMLElement {
  static observedAttributes = ['type', 'size', 'state', 'flush', 'rotulo', 'disabled', 'href'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  render() {
    const type = eixo(this, 'type', TYPE, 'tertiary');
    const size = PORTE[this.getAttribute('size')] ? this.getAttribute('size') : 'md';
    const g = PORTE[size];
    const state = this.getAttribute('state') === 'error' ? 'error' : 'normal';
    const chave = (i) => ({ Type: type, State: state, Interacao: i });
    const p = papeisDe(SLUG, chave('normal'));
    const hover = estiloDa(papeisDe(SLUG, chave('hover')));
    const pressed = estiloDa(papeisDe(SLUG, chave('pressed')));
    const desligado = estiloDa(papeisDe(SLUG, chave('disabled')));
    // `flush` encosta o glifo na borda inicial da caixa, para acessório de barra
    // sem superfície: sem ele, a caixa de 40 empurra o glifo 11px pra dentro e a
    // seta de voltar não alinha com o conteúdo da tela.
    //
    // ELE DESLOCA A CAIXA, e não o glifo dentro dela. Era `justify-content:
    // flex-start`, que move só o glifo — e aí a pílula de hover fica centrada na
    // CAIXA enquanto o glifo está no início dela, 11px de desencontro. A premissa
    // do nome é «acessório SEM superfície», e ela cai justamente no `:hover`, que
    // é quando a superfície existe. Medido no lado Dart pelo QA de um filho, no
    // botão de fechar de um onboarding; a instância web tinha o mesmo defeito em
    // outra forma, e as duas fecham na v0.176.0.
    //
    // O glifo não muda de lugar: a caixa anda `-recuo` e ele volta ao centro dela.
    const flush = ['left', 'right'].includes(this.getAttribute('flush'))
      ? this.getAttribute('flush') : null;
    const off = this.hasAttribute('disabled');
    const href = this.getAttribute('href');
    const tag = href && !off ? 'a' : 'button';

    // O RÓTULO É OBRIGATÓRIO e não é decoração: um botão só de glifo, sem nome
    // acessível, é anunciado como "botão" e nada mais. A spec do DS trata isso
    // como parte da peça, não como cuidado de quem chama.
    const rotulo = (this.getAttribute('rotulo') || '').replace(/"/g, '&quot;');

    this.shadowRoot.innerHTML = `
      <style>
        /* O ALVO fica FORA da caixa pintada nos portes pequenos: 32 de desenho
           dentro de 44 de alvo. Mesmo arranjo do chip e do botão. */
        :host { display: inline-flex; align-items: center; justify-content: center;
                min-width: ${ALVO}px; min-height: ${ALVO}px; }
        .botao {
          box-sizing: border-box;
          width: ${g.box}px; height: ${g.box}px;
          display: inline-flex; align-items: center; justify-content: center;
          border-width: 1px; border-style: solid; border-color: transparent;
          border-radius: 999px; padding: 0;
          cursor: pointer; text-decoration: none;
          ${estiloDa(p)}
          ${flush ? `transform: translateX(${flush === 'left' ? '-' : ''}${(g.box - g.icone) / 2}px);` : ''}
        }
        .botao:hover:not(:disabled) { ${hover} }
        .botao:active:not(:disabled) { ${pressed} }
        .botao:disabled { ${desligado} cursor: default; }
        .botao:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
        ::slotted(svg) { width: ${g.icone}px; height: ${g.icone}px; }
      </style>
      <${tag} class="botao" part="botao" aria-label="${rotulo}"
        ${tag === 'button' ? `type="button"${off ? ' disabled' : ''}`
                           : `href="${href.replace(/"/g, '&quot;')}"`}
        ><slot></slot></${tag}>`;
  }
}

customElements.define('diletta-icon-button', DilettaIconButton);
export { DilettaIconButton, PORTE, ALVO };
